-- 📚 꼭집 주거 사전 — 보증금↔월임대료 전환 이율 · SH · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.8초 · 결과:
-- {"anns": {"경상북도개발공사": 1, "광명도시공사": 2, "부산도시공사": 1, "서울주택도시개발공사": 4}, "rates": [{"org": "경상북도개발공사", "id": "20750_경상북도_구미시", "v": [3.5, 7]}, {"org": "서울주택도시개발공사", "id": "SH_310650", "v": [2.5, 6.7]}, {"org": "서울주택도시개발공사", "id": "SH_310653", "v": [2.5, 6.7]}]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),r as(select distinct y.announcement_id,y.org,x[1]::numeric v from y cross join lateral regexp_matches(y.t,'(?:연|이율|요율)\s*[:)]?\s*([0-9]+(?:\.[0-9]+)?)\s*%','g')x where y.cls='보증금 전환' and y.org<>'LH')select json_build_object('anns',(select json_object_agg(org,n) from(select org,count(distinct announcement_id)n from y where cls='보증금 전환' and org<>'LH' group by 1)q),'rates',(select json_agg(json_build_object('org',org,'id',announcement_id,'v',vs)) from(select org,announcement_id,array_agg(v order by v)vs from r group by 1,2)q))j;
